CREATE COLUMN TABLE "TEST_AP"."OQRC" ("AbsEntry" INTEGER CS_INT NOT NULL , "FileContnt" BLOB MEMORY THRESHOLD 1000, "SrcObjType" INTEGER CS_INT NOT NULL , "SrcObjAbs" NVARCHAR(20) NOT NULL , "FieldName" NVARCHAR(50) NOT NULL , "ExpAfter" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "CreateTS" INTEGER CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "UpdateTS" INTEGER CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OQRC_SECONDARY" ON "TEST_AP"."OQRC" ( "SrcObjType" ASC, "SrcObjAbs" ASC, "FieldName" ASC )